1	package main
2	
3	import (
4		"context"
5		"errors"
6		"log"
7		"net/http"
8		"os"
9		"os/signal"
10		"syscall"
11		"time"
12	
13		"github.com/jackc/pgx/v5/pgxpool"
14		"github.com/lansolocoder/cla03-entitlement-service/internal/entitlements"
15		"github.com/lansolocoder/cla03-entitlement-service/internal/httpapi"
16	)
17	
18	func main() {
19		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
20		defer stop()
21		databaseURL := os.Getenv("DATABASE_URL")
22		if databaseURL == "" {
23			log.Fatal("DATABASE_URL is required")
24		}
25		pool, err := pgxpool.New(ctx, databaseURL)
26		if err != nil {
27			log.Fatal("invalid database configuration")
28		}
29		defer pool.Close()
30		store := entitlements.NewStore(pool)
31		if err := store.Migrate(ctx); err != nil {
32			log.Fatal("schema migration failed: ", err)
33		}
34		address := os.Getenv("LISTEN_ADDR")
35		if address == "" {
36			address = "127.0.0.1:8080"
37		}
38		server := &http.Server{
39			Addr: address, Handler: httpapi.New(pool.Ping, store),
40			ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 10 * time.Second,
41			WriteTimeout: 10 * time.Second, IdleTimeout: 60 * time.Second,
